import{_ as e,c as a,o as r,ae as o}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse(`{"title":"Update Cart Item","description":"","frontmatter":{"outline":false,"examples":[{"id":"update-cart-item","title":"Update Cart Item","description":"Change the quantity of a cart line. Both cartItemId and quantity are required.","request":"curl -X POST \\"http://localhost/api/shop/update-cart-item\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\" \\\\\\n  -H \\"Authorization: Bearer 62f2b3f5-a455-4c78-93ba-eabca63d32ec\\" \\\\\\n  -d '{\\n        \\"cartItemId\\": 358,\\n        \\"quantity\\": 3\\n      }'\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 495,\\n  \\"cartToken\\": \\"62f2b3f5-a455-4c78-93ba-eabca63d32ec\\",\\n  \\"itemsCount\\": 1,\\n  \\"items\\": [\\n    {\\n      \\"id\\": 358,\\n      \\"cartId\\": 495,\\n      \\"productId\\": 2,\\n      \\"name\\": \\"Blossom Breeze Cotton Printed Short Skirt\\",\\n      \\"sku\\": \\"ws-blossom-skirt\\",\\n      \\"quantity\\": 3,\\n      \\"price\\": 24.99,\\n      \\"total\\": 74.97,\\n      \\"formattedPrice\\": \\"$24.99\\",\\n      \\"formattedTotal\\": \\"$74.97\\",\\n      \\"type\\": \\"simple\\",\\n      \\"canChangeQty\\": true\\n    }\\n  ],\\n  \\"subtotal\\": 74.97,\\n  \\"discountAmount\\": 0,\\n  \\"taxAmount\\": 0,\\n  \\"shippingAmount\\": 0,\\n  \\"grandTotal\\": 74.97,\\n  \\"formattedSubtotal\\": \\"$74.97\\",\\n  \\"formattedGrandTotal\\": \\"$74.97\\",\\n  \\"couponCode\\": null,\\n  \\"isGuest\\": true\\n}\\n","commonErrors":[{"error":"400 Bad Request — Cart item ID and quantity are required","cause":"One of the two fields was missing, or quantity was sent as 0","solution":"Send both; use Remove Cart Item to take the line out entirely"},{"error":"401 Unauthorized — Authentication token is required","cause":"No cart or customer token was sent as the Bearer token","solution":"Send the cartToken from Create Cart, or a logged-in customer's token"},{"error":"success true but nothing changed","cause":"cartItemId does not match a line on this cart — often a product id was sent instead","solution":"Read items[].id from the cart payload and compare the line back after the call"}]}]},"headers":[],"relativePath":"api/rest-api/shop/cart/update-cart-item.md","filePath":"api/rest-api/shop/cart/update-cart-item.md"}`),n={name:"api/rest-api/shop/cart/update-cart-item.md"};function d(s,t,i,c,l,h){return r(),a("div",null,t[0]||(t[0]=[o(`<h1 id="update-cart-item" tabindex="-1">Update Cart Item <a class="header-anchor" href="#update-cart-item" aria-label="Permalink to &quot;Update Cart Item&quot;">​</a></h1><p>Change the quantity of a line already in the cart.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/update-cart-item</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>The cart&#39;s own token as a Bearer token, or a logged-in customer&#39;s token.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cartItemId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">372</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;quantity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>cartItemId</code></td><td>integer</td><td>Yes</td><td>The <strong>cart line</strong> id from <code>items[].id</code> — not the product id.</td></tr><tr><td><code>quantity</code></td><td>integer</td><td>Yes</td><td>New quantity. Must be 1 or more.</td></tr></tbody></table><p>Both fields are required together, and the check rejects <code>0</code> as well as a missing value — the shared message is <code>Cart item ID and quantity are required</code>. Removing a line is a separate call, <a href="/api/rest-api/shop/cart/remove-cart-item.html">Remove Cart Item</a>, not a quantity of zero.</p><p>Product options cannot be changed here. To switch a variant or an option selection, remove the line and add the product again with the new choice.</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>201 Created</code> carrying the whole recalculated cart — the same object <a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> returns, plus <code>success</code> and <code>message</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>success</code></td><td>boolean</td><td><code>true</code> when the call completed.</td></tr><tr><td><code>message</code></td><td>string</td><td><code>Cart item updated successfully</code>.</td></tr><tr><td><code>items[].quantity</code></td><td>integer</td><td>The new quantity on the updated line.</td></tr><tr><td><code>subtotal</code> / <code>grandTotal</code> and their <code>formatted*</code> twins</td><td>number / string</td><td>Recalculated totals.</td></tr></tbody></table><p>An unknown <code>cartItemId</code> also answers <code>201</code> with <code>success: true</code> and an unchanged cart — the call is a silent no-op rather than a <code>404</code>. Verify by reading the line back from <code>items</code>.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Result</th></tr></thead><tbody><tr><td><code>cartItemId</code> and <code>quantity</code> both present, quantity at least 1</td><td>Otherwise <code>400 Cart item ID and quantity are required</code>.</td></tr><tr><td>A Bearer token identifies the cart</td><td>Otherwise <code>401 Authentication token is required</code>.</td></tr><tr><td>Requested quantity is available</td><td>Stock is enforced by the cart, which trims the line and reports the change in the returned totals.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Quantity stepper on the cart page</strong> — post the new quantity and re-render from the returned cart.</li><li><strong>&quot;Move to 1 before checkout&quot; flows</strong> — the same call handles both increase and decrease.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Confirm the change from <code>items</code>, not from <code>success</code></strong> — a wrong line id reports success while changing nothing.</li><li><strong>Send the line id, not the product id</strong> — a product id normally matches no line and is silently ignored.</li><li><strong>Use the remove endpoint for zero</strong> — quantity <code>0</code> is rejected as a missing value.</li><li><strong>Re-render totals from the response</strong> — the payload is the full recalculated cart, so no follow-up fetch is needed.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> — read the current items and recalculated totals</li><li><a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a> — add a product of any type to the cart</li><li><a href="/api/rest-api/shop/cart/remove-cart-item.html">Remove Cart Item</a> — remove one line, or several in one call</li></ul>`,23)]))}const m=e(n,[["render",d]]);export{p as __pageData,m as default};
